          }
        ]
      },
      "figure_role": "read_off",
      "source_quote": "A picture showing 6 tens circles and 1 loose counter, representing the number 61.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Which of these are 'tens' and 'ones'?",
      "options": [
        "place value",
        "2-digit numbers",
        "counting"
      ],
      "correct_index": 0,
      "explanation": "Tens and ones are terms used to describe the place value of digits in 2-digit numbers.",
      "selected_because": "The SLO explicitly mentions 'tens' and 'ones' as parts of place value.",
      "distractor_misconceptions": {
        "1": "Confuses parts of a number with the type of number",
        "2": "Confuses parts of a number with a mathematical operation"
      },
      "option_feedback": {
        "correct": "That's right! 'Tens' and 'ones' are terms used to describe place value in 2-digit numbers.",
        "wrong": {
          "1": "Not quite. 'Tens' and 'ones' are parts of place value, which helps us understand 2-digit numbers. They are not the 2-digit numbers themselves.",
          "2": "No, 'tens' and 'ones' are about the value of digits in a number, not about the act of counting."
        }
      },
